{
  "case_id": "xsu_sg_002_permanence_requirement",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret gengiver korrekt definitionen af varig og étårsudgangspunktet før ansøgningen. Det udelader dog, at tidsbegrænset tillæg kan gives, når varighed er sandsynliggjort men ikke endeligt fastslået. Det giver et ufuldstændigt billede af, hvad der gælder, hvis tilstanden ikke er varig fra begyndelsen. Svaret er derfor ikke fuldt dækkende i forhold til rubrikken. Udsagnene i sig selv er ikke direkte forkerte."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Tre af fire kritiske elementer er med: udgangspunktet om bedring, étårsregelen og tiden før ansøgningen. Elementet om, at varighed er grundlæggende og vedrører art og grad, er kun svagt dækket. Elementet om tidsbegrænset tillæg ved sandsynliggjort men ikke endeligt fastslået varighed mangler helt."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret besvarer begge dele af spørgsmålet: hvornår en funktionsnedsættelse er varig, og hvad der gælder, hvis den ikke er varig fra begyndelsen. Der er ingen irrelevant tekst."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde som lovbestemmelse, vejledningsafsnit eller lignende."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så det ikke kan vurderes, om kilden understøtter påstandene."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "met",
      "reason": "Alle udsagn svarer til vejledningens afsnit 3.4.1.1. Svaret tilføjer ingen regel, betingelse eller myndighed, som mangler støtte."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "Svaret bevarer 'som udgangspunkt', 'omkring et år', 'kan vurderes' og 'normalt'. Det får også med, at étårsreglen gælder før ansøgningstidspunktet. Det siger ikke eksplicit, at tiden alene ikke afgør varigheden, men 'kan vurderes' og 'som udgangspunkt' bevarer den ikke-absolutte karakter. Undtagelsen om tidsbegrænset tillæg mangler, men den hører under C02."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende. Først kommer definitionen af varig, derefter udgangspunktet for tilstande, der ikke er varige fra begyndelsen, og til sidst étårsvurderingen. Konklusionen følger af disse trin."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "Svaret gengiver modaliteten korrekt med 'som udgangspunkt', 'kan dog vurderes' og 'normalt'. Det gør ikke vejledningens udgangspunkter til absolutte regler."
    }
  },
  "xhaile_coverage": {
    "A9": {
      "label": "partial",
      "reason": "Svaret behandler varig funktionsnedsættelse og definerer begrebet. Det fremhæver ikke udtrykkeligt varighed som en af betingelserne for tillægget eller som en forudsætning, der knytter sig til art og grad."
    },
    "A12": {
      "label": "yes",
      "reason": "Svaret dækker punktet i det væsentlige ordret: som udgangspunkt ikke berettiget, hvis tilstanden ikke var varig eller kronisk fra debut, kan vurderes som varig ved omkring et år, og normalt mindst et års symptomer før ansøgningen."
    }
  },
  "overall_notes": "Svaret er korrekt og præcist på étårsudgangspunktet og definitionen af varig, men det mangler muligheden for tidsbegrænset tillæg ved sandsynliggjort varighed. Det angiver desuden ingen kilder, så C04 er not_met, og C05 og C06 er not_assessable."
}

